mapper.select:
SELECT COALESCE(SUM(file_size), 0)
FROM file_node
WHERE deleted IN (0, 1) AND file_type = 1

    AND space_type = 3 AND project_id = #{projectId}
    AND space_type = 2 AND team_id = #{teamId}
    AND (space_type IS NULL OR space_type = 1) AND team_id IS NULL AND upload_user_id = #{userId}

SELECT scope_key AS scopeKey, COALESCE(SUM(file_size), 0) AS totalBytes FROM file_node WHERE id IN
#{fileId}
AND file_size IS NOT NULL GROUP BY scope_key

SELECT f.id
FROM file_node f
WHERE f.deleted = 1
  AND f.modify_time < #{cutoff}
  AND NOT EXISTS (
        SELECT 1 FROM file_node p
        WHERE p.id = f.parent_id AND p.deleted = 1
  )
LIMIT #{limit}

SELECT id FROM file_node
WHERE deleted = 2
  AND modify_time < #{cutoff}
LIMIT #{limit}

SELECT id, file_type, original_name, category, file_size,
parent_id, team_id AS teamId, create_time, modify_time
FROM file_node
WHERE deleted = 0

    AND team_id IS NULL AND upload_user_id = #{userId}
    AND team_id = #{teamId}

AND original_name LIKE CONCAT(#{keyword}, '%')
ORDER BY modify_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT upload_user_id AS userId, COALESCE(SUM(file_size), 0) AS usedStorage FROM file_node WHERE deleted IN (0, 1) AND file_type = 1 AND (space_type IS NULL OR space_type = 1) AND team_id IS NULL AND upload_user_id IN
#{userId}
GROUP BY upload_user_id

SELECT team_id AS teamId, COALESCE(SUM(file_size), 0) AS usedStorage FROM file_node WHERE deleted IN (0, 1) AND file_type = 1 AND space_type = 2 AND team_id IN
#{teamId}
GROUP BY team_id

SELECT project_id AS projectId, COALESCE(SUM(file_size), 0) AS usedStorage FROM file_node WHERE deleted IN (0, 1) AND file_type = 1 AND space_type = 3 AND project_id IN
#{projectId}
GROUP BY project_id

SELECT id, file_type, uuid_name, original_name, category, file_size, file_url, store_path,
       upload_user_id, shared_user_id, team_id, space_type, project_id, deleted_user_id, parent_id, create_time, modify_time, deleted, storage_provider
FROM file_node f
WHERE f.deleted = 1
  AND NOT EXISTS (
      SELECT 1 FROM file_node p
      WHERE p.id = f.parent_id AND p.deleted = 1
  )

    AND f.space_type = 3 AND f.project_id = #{projectId}
    AND (f.space_type IS NULL OR f.space_type = 1) AND f.team_id IS NULL AND f.upload_user_id = #{userId}
    AND f.team_id = #{teamId}

ORDER BY modify_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM file_node f
WHERE f.deleted = 1
  AND NOT EXISTS (
      SELECT 1 FROM file_node p
      WHERE p.id = f.parent_id AND p.deleted = 1
  )

    AND f.space_type = 3 AND f.project_id = #{projectId}
    AND (f.space_type IS NULL OR f.space_type = 1) AND f.team_id IS NULL AND f.upload_user_id = #{userId}
    AND f.team_id = #{teamId}

SELECT id, file_type, uuid_name, original_name, category, file_size, file_url, store_path, upload_user_id, shared_user_id, team_id, space_type, project_id, deleted_user_id, parent_id, create_time, modify_time, deleted, storage_provider
FROM file_node
WHERE parent_id = #{parentId} AND deleted = 0

    AND space_type = 3 AND project_id = #{projectId}
    AND (space_type IS NULL OR space_type = 1) AND team_id IS NULL AND (#{userId} IS NULL OR upload_user_id = #{userId})
    AND team_id = #{teamId}

SELECT id, file_type, uuid_name, original_name, category, file_size, file_url, store_path, upload_user_id, shared_user_id, team_id, space_type, project_id, deleted_user_id, parent_id, create_time, modify_time, deleted, storage_provider
FROM file_node
WHERE parent_id = #{parentId} AND deleted = 0

    AND space_type = 3 AND project_id = #{projectId}
    AND (space_type IS NULL OR space_type = 1) AND team_id IS NULL AND (#{userId} IS NULL OR upload_user_id = #{userId})
    AND team_id = #{teamId}

ORDER BY file_type DESC, original_name ASC
LIMIT #{limit} OFFSET #{offset}

SELECT id, file_type, uuid_name, original_name, category, file_size, file_url, store_path, upload_user_id, shared_user_id, team_id, deleted_user_id, parent_id, create_time, modify_time, deleted, storage_provider
FROM file_node
WHERE parent_id = #{parentId}

    AND team_id IS NULL AND (#{userId} IS NULL OR upload_user_id = #{userId})
    AND team_id = #{teamId}

WITH RECURSIVE descendants AS ( SELECT id, file_type, uuid_name, original_name, category, file_size, file_url, store_path, upload_user_id, shared_user_id, team_id, space_type, project_id, deleted_user_id, parent_id, create_time, modify_time, deleted, storage_provider FROM file_node WHERE parent_id IN
#{parentId}
AND deleted = 0 UNION ALL SELECT c.id, c.file_type, c.uuid_name, c.original_name, c.category, c.file_size, c.file_url, c.store_path, c.upload_user_id, c.shared_user_id, c.team_id, c.space_type, c.project_id, c.deleted_user_id, c.parent_id, c.create_time, c.modify_time, c.deleted, c.storage_provider FROM file_node c INNER JOIN descendants d ON c.parent_id = d.id WHERE c.deleted = 0 ) SELECT id, file_type, uuid_name, original_name, category, file_size, file_url, store_path, upload_user_id, shared_user_id, team_id, space_type, project_id, deleted_user_id, parent_id, create_time, modify_time, deleted, storage_provider FROM descendants
